// Curated "deep dive" pages for a small pilot set of historically major
// empires/civilizations: a detailed year-by-year timeline, key
// historical figures, and a 20-question quiz, all hand-written (same
// curation approach as territorySummaries.ts and knownGapPeoples.ts —
// no live API calls, works offline).
//
// Each entry is linked to the main map via `datasetNames`: the exact
// NAME/SUBJECTO strings this civilization appears under across the
// vendored snapshots (a single civilization is often split across many
// dataset names as it changes form over centuries, e.g. Rome / Roman
// Republic / Roman Empire / Western Roman Empire / Byzantine Empire).
export type Milestone = {
  year: number;
  label: string;
  title: string;
  text: string;
};

export type KeyFigure = {
  name: string;
  years: string;
  text: string;
};

export type QuizQuestion = {
  question: string;
  options: string[];
  correctIndex: number;
  explanation: string;
};

export type EmpireDeepDive = {
  slug: string;
  ptName: string;
  datasetNames: string[];
  // Some dataset names are reused across many centuries for the same
  // NAME string (e.g. "France" spans the medieval kingdom, the
  // Napoleonic Empire and the modern republic). When a dive covers only
  // one era of such a name, set yearRange to the [from, to] snapshot
  // years where the match should apply — outside that range, clicking
  // the territory falls back to the normal era-aware summary instead.
  // Omit for dataset names that are inherently unambiguous (e.g. "Aztec
  // Empire", "Byzantine Empire").
  yearRange?: [number, number];
  // Slugs of other dives that are historically continuous with this one
  // (predecessor/successor nations, or a mainland vs. colonial split),
  // shown as "Ver também" links on the deep-dive page. Not necessarily
  // symmetric in the source data, but kept symmetric by convention.
  relatedSlugs?: string[];
  intro: string;
  milestones: Milestone[];
  keyFigures: KeyFigure[];
  quiz: QuizQuestion[];
};

