export function deepDiveForTerritory(name: string, year?: number): EmpireDeepDive | null {
  return (
    EMPIRE_DEEP_DIVES.find((dive) => {
      if (!dive.datasetNames.includes(name)) return false;
      if (!dive.yearRange) return true;
      if (year == null) return false;
      const [from, to] = dive.yearRange;
      return year >= from && year <= to;
    }) ?? null
  );
}

export function deepDiveBySlug(slug: string): EmpireDeepDive | null {
  return EMPIRE_DEEP_DIVES.find((dive) => dive.slug === slug) ?? null;
}
